def candidate_paths_for_url(self, url):
    for root, prefix in self.directories:
        if url.startswith(prefix):
            path = os.path.join(root, url[len(prefix):])
            if os.path.commonprefix((root, path)) == root:
                yield path

def render(self, request):
	action = "download"
	if "action" in request.args:
		action = request.args["action"][0]

	if "file" in request.args:
		filename = lenient_force_utf_8(request.args["file"][0])
		filename = sanitise_filename_slashes(os.path.realpath(filename))

		if not os.path.exists(filename):
			return "File '%s' not found" % (filename)

		if action == "stream":
			name = "stream"
			if "name" in request.args:
				name = request.args["name"][0]

			port = config.OpenWebif.port.value
			proto = 'http'
			if request.isSecure():
				port = config.OpenWebif.https_port.value
				proto = 'https'
			ourhost = request.getHeader('host')
			m = re.match('.+\:(\d+)$', ourhost)
			if m is not None:
				port = m.group(1)

			response = "#EXTM3U\n#EXTVLCOPT--http-reconnect=true\n#EXTINF:-1,%s\n%s://%s:%s/file?action=download&file=%s" % (name, proto, request.getRequestHostname(), port, quote(filename))
			request.setHeader("Content-Disposition", 'attachment;filename="%s.m3u"' % name)
			request.setHeader("Content-Type", "application/x-mpegurl")
			return response
		elif action == "delete":
			request.setResponseCode(http.OK)
			return "TODO: DELETE FILE: %s" % (filename)
		elif action == "download":
			request.setHeader("Content-Disposition", "attachment;filename=\"%s\"" % (filename.split('/')[-1]))
			rfile = static.File(filename, defaultType = "application/octet-stream")
			return rfile.render(request)
		else:
			return "wrong action parameter"

	if "dir" in request.args:
		path = request.args["dir"][0]
		pattern = '*'
		data = []
		if "pattern" in request.args:
			pattern = request.args["pattern"][0]
		directories = []
		files = []
		if fileExists(path):
			try:
				files = glob.glob(path+'/'+pattern)
			except:
				files = []
			files.sort()
			tmpfiles = files[:]
			for x in tmpfiles:
				if os.path.isdir(x):
					directories.append(x + '/')
					files.remove(x)
			data.append({"result": True,"dirs": directories,"files": files})
		else:
			data.append({"result": False,"message": "path %s not exits" % (path)})
		request.setHeader("content-type", "application/json; charset=utf-8")
		return json.dumps(data, indent=2)

def _formatCredentials(self, data, name):







    prefix = "RCLONE_CONFIG_{}".format(name.upper())

    credentials = ''
    credentials += "{}_TYPE='{}' ".format(prefix, data.type)

    def _addCredential(credentials, env_key, data_key):
        value = getattr(data, data_key, None)
        if value is not None:
            credentials += "{}='{}' ".format(env_key, value)
        return credentials


    if data.type == 's3':
        credentials = _addCredential(credentials,
            '{}_REGION'.format(prefix),
            's3_region'
        )
        credentials = _addCredential(credentials,
            '{}_ACCESS_KEY_ID'.format(prefix),
            's3_access_key_id'
        )
        credentials = _addCredential(credentials,
            '{}_SECRET_ACCESS_KEY'.format(prefix),
            's3_secret_access_key'
        )

        credentials = _addCredential(credentials,
            '{}_ENDPOINT'.format(prefix),
            's3_endpoint'
        )
        credentials = _addCredential(credentials,
            '{}_V2_AUTH'.format(prefix),
            's3_v2_auth'
        )

    elif data.type == 'azureblob':
        credentials = _addCredential(credentials,
            '{}_ACCOUNT'.format(prefix),
            'azure_account'
        )
        credentials = _addCredential(credentials,
            '{}_KEY'.format(prefix),
            'azure_key'
        )

    elif data.type == 'swift':
        credentials = _addCredential(credentials,
            '{}_USER'.format(prefix),
            'swift_user'
        )
        credentials = _addCredential(credentials,
            '{}_KEY'.format(prefix),
            'swift_key'
        )
        credentials = _addCredential(credentials,
            '{}_AUTH'.format(prefix),
            'swift_auth'
        )
        credentials = _addCredential(credentials,
            '{}_TENANT'.format(prefix),
            'swift_tenant'
        )

    elif data.type == 'google cloud storage':
        credentials = _addCredential(credentials,
            '{}_CLIENT_ID'.format(prefix),
            'gcp_client_id'
        )
        credentials = _addCredential(credentials,
            '{}_SERVICE_ACCOUNT_CREDENTIALS'.format(prefix),
            'gcp_service_account_credentials'
        )
        credentials = _addCredential(credentials,
            '{}_PROJECT_NUMBER'.format(prefix),
            'gcp_project_number'
        )
        credentials = _addCredential(credentials,
            '{}_OBJECT_ACL'.format(prefix),
            'gcp_object_acl'
        )
        credentials = _addCredential(credentials,
            '{}_BUCKET_ACL'.format(prefix),
            'gcp_bucket_acl'
        )

    else:
        logging.error("Connection type unknown: {}".format(data.type))

    return credentials

