      app.session.user &&
      app.session.user.id() !== user.id() &&
      app.forum.attribute('canStartPrivateDiscussion') &&
      (user.blocksPd() === false || (app.forum.attribute('canStartPrivateDiscussionWithBlockers') && user.cannotBeDirectMessaged()))
    ) {
