            $("#account-settings .privacy-setting-status").expectOne(),
        );
    });
}

function esc(value) {
	value = (value == null) ? '' : '' + value;
	let last=ESCAPE.lastIndex=0, tmp=0, out='';
	while (ESCAPE.test(value)) {
		tmp = ESCAPE.lastIndex - 1;
		out += value.substring(last, tmp) + CHARS[value[tmp]];
		last = tmp + 1;
	}
	return out + value.substring(last);
}

function escapeShellArg(arg) {
  return arg.replace(/'/g, `'\\''`);
}

function renderRestrictedPipeline(node) {
        var gui = '';
        gui += '<h3 title="' + node.name + '" class="restricted">' + node.name + '</h3>';
        if (node.message) {
            gui += '<div class="message restricted"><span>' + node.message + '</span></div>';
        }
        gui += '<div class="actions restricted">';
        gui += '<button class="pin" title="Keep dependencies highlighted" /></div>';
        return gui;
    }
